pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 initialBalance, uint256 addAmount) public {
        // Bound addAmount to avoid overflow in the reference assertion itself, but keep it wide enough
        // to allow the buggy wrap-around to happen.
        vm.assume(addAmount > 0);
        vm.assume(initialBalance < type(uint256).max);
        // Pick a fixed caller to avoid needing prank before reading getBalance
        address caller = address(0x100);
        // Set up initial balance by calling addToBalance with initialBalance value
        vm.deal(caller, initialBalance);
        vm.prank(caller);
        c.addToBalance{value: initialBalance}();
        uint256 balanceBefore = c.getBalance(caller);
        // Fund the caller again for the actual test call
        vm.deal(caller, addAmount);
        vm.prank(caller);
        c.addToBalance{value: addAmount}();
        uint256 balanceAfter = c.getBalance(caller);
        // The general rule: balance must not decrease after adding a positive amount.
        // In the reference, safe_add ensures overflow reverts, so balanceAfter >= balanceBefore always holds.
        // In the buggy version, overflow wraps around, making balanceAfter < balanceBefore for some inputs.
        assertTrue(balanceAfter >= balanceBefore);
    }
}

