pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount, uint256 reentrantAmount) public {
        // Restrict amounts to admissible range: non-zero and such that sum fits in uint256
        vm.assume(depositAmount > 0);
        vm.assume(withdrawAmount > 0);
        vm.assume(reentrantAmount > 0);
        vm.assume(depositAmount + reentrantAmount > depositAmount); // overflow check

        // Deploy a reentrant attacker that calls addToBalance during its receive()
        ReentrantAttacker attacker = new ReentrantAttacker(address(c));

        // Fund attacker with enough Ether for deposit
        vm.deal(address(attacker), depositAmount + reentrantAmount);

        // Attacker deposits "depositAmount" into C
        vm.prank(address(attacker));
        c.addToBalance{value: depositAmount}();

        // Attacker now has userBalance[attacker] = depositAmount
        // Attacker initiates withdrawBalance: C sends depositAmount Ether to attacker.
        // Attacker's receive() is triggered, which calls addToBalance with reentrantAmount.
        // In buggy version, reentrancy guard is broken, so the reentrant addToBalance
        // increases another user's balance (attacker's) while the original withdrawBalance
        // hasn't yet zeroed it. In correct version, the guard prevents reentry, so addToBalance
        // during withdrawBalance reverts.
        vm.prank(address(attacker));
        try c.withdrawBalance() {
            // For correct version, this succeeds without reentrant deposit occuring.
            // After withdrawal, userBalance[attacker] should be 0.
        } catch {
            // Buggy version may revert if reentrant call fails or other reasons, but the invariant
            // is checked below regardless.
        }

        // Invariant: userBalance of any address other than the caller of withdrawBalance
        // must be zero after withdrawBalance completes. Since withdrawBalance is called by attacker,
        // the attacker's own balance should be zero in correct version, but in buggy version
        // it might be non-zero if reentrancy succeeded. Additionally, no other address should have
        // a non-zero balance. We check that userBalance[attacker] is zero (correct) vs non-zero (bug).
        // However, to make it general, we assert that after any sequence starting from addToBalance
        // and finishing with withdrawBalance, no balance exists that wasn't directly deposited
        // by that user. But the simpler universal invariant is: after withdrawBalance, the caller's
        // balance must be zero. In correct version, this holds. In buggy version, reentrancy
        // can leave a positive balance.
        assertTrue(c.getBalance(address(attacker)) == 0);
    }
}

contract ReentrantAttacker {
    C public target;
    uint256 public reentrantAmount;

    constructor(address _target) {
        target = C(_target);
    }

    receive() external payable {
        // Reentrant call to addToBalance
        target.addToBalance{value: reentrantAmount}();
    }

    // Fallback just in case
    fallback() external payable {
        target.addToBalance{value: reentrantAmount}();
    }

    function setReentrantAmount(uint256 _amount) external {
        reentrantAmount = _amount;
    }
}

