pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount1, uint256 amount2) public {
        // bound amounts to avoid overflow in sum, but keep wide
        amount1 = bound(amount1, 0, type(uint256).max / 2);
        amount2 = bound(amount2, 0, type(uint256).max / 2);
        vm.assume(amount1 <= type(uint256).max - amount2);

        // deploy an attacker contract that re-enters c.addToBalance during withdrawBalance
        ReentrantAttacker attacker = new ReentrantAttacker();
        vm.deal(address(attacker), amount1 + amount2);

        // attacker deposits amount1
        attacker.deposit{value: amount1}(c);
        // attacker triggers withdraw and re-enters with amount2
        attacker.attack{value: amount2}(c);

        // after all calls, total contract ETH must equal sum of all recorded userBalance
        uint256 totalBalance;
        totalBalance += c.getBalance(address(attacker));
        totalBalance += c.getBalance(address(this));
        totalBalance += c.getBalance(address(0)); // unlikely but included
        assertTrue(address(c).balance == totalBalance);
    }
}

contract ReentrantAttacker {
    C public target;
    uint256 public depositAmount;
    bool public reentered;

    function deposit(C _c) external payable {
        target = _c;
        depositAmount = msg.value;
        _c.addToBalance{value: msg.value}();
    }

    function attack(C _c) external payable {
        target = _c;
        _c.addToBalance{value: msg.value}(); // deposit msg.value (amount2)
        reentered = false;
        _c.withdrawBalance();
    }

    receive() external payable {
        if (!reentered) {
            reentered = true;
            // re-enter addToBalance with depositAmount already withdrawn? No, we re-enter with the full balance we had before withdrawal
            // actually during withdrawBalance, msg.sender.call sends us our balance (which includes initial deposit + amount2)
            // we re-enter addToBalance with part of that received ether
            target.addToBalance{value: depositAmount}(); // send back the initial deposit amount as new deposit
        }
    }
}

