pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address attacker) public {
        vm.assume(amount > 0 && amount < type(uint256).max / 2);
        vm.assume(attacker != address(0) && attacker != address(this) && attacker != address(c));

        // Deploy a re-entrant attacker that calls addToBalance during withdrawBalance
        Reenterer reenterer = new Reenterer(c);
        address attackerAddr = address(reenterer);

        // Fund the contract with some Ether
        vm.deal(address(c), amount);
        // Give the attacker some ETH to trigger withdrawBalance
        vm.deal(attackerAddr, amount);

        // Attacker deposits some ETH to get a balance
        vm.prank(attackerAddr);
        c.addToBalance{value: amount}();

        // Now attacker calls withdrawBalance, which triggers re-entry
        vm.prank(attackerAddr);
        c.withdrawBalance();

        // After all calls, no user's balance should exceed the contract's Ether balance
        uint256 contractBalance = address(c).balance;
        uint256 attackerBalance = c.getBalance(attackerAddr);
        assertTrue(attackerBalance <= contractBalance);
    }
}

contract Reenterer {
    C target;
    bool private reentered;
    constructor(C _target) { target = _target; }
    receive() external payable {
        if (!reentered) {
            reentered = true;
            target.addToBalance();
        }
    }
    fallback() external payable {
        if (!reentered) {
            reentered = true;
            target.addToBalance();
        }
    }
}

