        vm.prank(caller);
        c.withdrawBalance();

        // Now deposit exactly withdrawAmount
        vm.prank(caller);
        c.addToBalance{value: withdrawAmount}();
        uint256 balanceBefore = c.getBalance(caller);
        uint256 contractBalanceBeforeWithdraw = address(c).balance;

        // Perform the withdrawal
        vm.prank(caller);
        try c.withdrawBalance() {} catch {}

        // Property: Contract balance decreased by exactly balanceBefore
        assertTrue(address(c).balance == contractBalanceBeforeWithdraw - balanceBefore);
